declare(strict_types=1);define('ATLAS_PLATFORM_DIR',dirname(__DIR__).'/plugin/atlas-platform/');require ATLAS_PLATFORM_DIR.'src/Autoloader.php';Atlas\Platform\Autoloader::register();if(!function_exists('wp_json_encode')){function wp_json_encode($value):string{return json_encode($value,JSON_THROW_ON_ERROR);}}use Atlas\Platform\Organizations\Domain\OrganizationPolicy;use Atlas\Platform\Organizations\Onboarding\OrganizationOnboardingRepository;use Atlas\Platform\Organizations\Onboarding\OrganizationOnboardingService;function onboard_expect(bool$c,string$m):void{if(!$c){throw new RuntimeException($m);}echo"PASS: {$m}\n";}$repository=new class implements OrganizationOnboardingRepository{public array$records=[];public function create(string$key,string$fingerprint,string$name,string$slug,int$userId):array{if(isset($this->records[$key])){if($this->records[$key]['fingerprint']!==$fingerprint){throw new RuntimeException('The idempotency key was already used for a different request.');}$result=$this->records[$key]['result'];$result['replayed']=true;return$result;}$result=['organization_id'=>'org-1','membership_id'=>'member-1','replayed'=>false];$this->records[$key]=compact('fingerprint','result');return$result;}};$service=new OrganizationOnboardingService($repository,new OrganizationPolicy());$first=$service->create('request-1','Atlas Clinic','atlas-clinic',42);$retry=$service->create('request-1','Atlas Clinic','atlas-clinic',42);onboard_expect(!$first['replayed']&&$retry['replayed'],'an identical onboarding retry returns the existing result');try{$service->create('request-1','Different Clinic','different-clinic',42);throw new RuntimeException('Expected conflict.');}catch(RuntimeException$failure){onboard_expect(str_contains($failure->getMessage(),'different request'),'idempotency-key reuse with different input conflicts');}try{$service->create('request-2','A','bad slug',42);throw new RuntimeException('Expected validation error.');}catch(InvalidArgumentException){onboard_expect(true,'organization input is normalized and validated before persistence');}echo"All organization onboarding tests passed.\n";
